figure.code:
type Query {
  login(username: String!, password: String!): AuthPayload
}

type AuthPayload {
  token: String!
  user: User!
}

type User {
  id: ID!
  username: String!
  email: String!
}

# Custom directive for auth metadata
directive @auth(requires: String) on FIELD_DEFINITION

syntax = "proto3";

package auth;

service AuthService {
  rpc Login(LoginRequest) returns (LoginResponse);
}

message LoginRequest {
  string username = 1;
  string password = 2;
}

message LoginResponse {
  string token = 1;
  User user = 2;
}

message User {
  string id = 1;
  string username = 2;
  string email = 3;
}
